program='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    exterior = set()
    queue = deque()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r in (0, h - 1) or c in (0, w - 1)):
                exterior.add((r, c))
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if (0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0
                    and (rr, cc) not in exterior):
                exterior.add((rr, cc))
                queue.append((rr, cc))

    interior = {(r, c) for r in range(h) for c in range(w)
                if grid[r][c] == 0 and (r, c) not in exterior}
    boundary = set()
    for r, c in interior:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 1:
                    boundary.add((rr, cc))

    result = [row[:] for row in grid]
    for r, c in interior:
        if any((r + dr, c + dc) in boundary
               for dr in (-1, 0, 1) for dc in (-1, 0, 1)):
